"use client";

import React, { useState, useRef, useEffect } from "react";
import { useRouter } from "next/navigation";
import { Search, ArrowRight, X } from "lucide-react";
import { searchTools, Tool } from "@/data/tools";
import Link from "next/link";

interface ToolSearchProps {
  placeholder?: string;
  className?: string;
  size?: "default" | "large";
}

export function ToolSearch({
  placeholder = "Search for a tool (e.g. compress image, merge PDF...)",
  className = "",
  size = "large",
}: ToolSearchProps) {
  const [query, setQuery] = useState("");
  const [results, setResults] = useState<Tool[]>([]);
  const [isOpen, setIsOpen] = useState(false);
  const router = useRouter();
  const containerRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (query.trim().length > 1) {
      const matched = searchTools(query);
      setResults(matched.slice(0, 6));
      setIsOpen(true);
    } else {
      setResults([]);
      setIsOpen(false);
    }
  }, [query]);

  // Handle outside click
  useEffect(() => {
    const handleClickOutside = (e: MouseEvent) => {
      if (containerRef.current && !containerRef.current.contains(e.target as Node)) {
        setIsOpen(false);
      }
    };
    document.addEventListener("mousedown", handleClickOutside);
    return () => document.removeEventListener("mousedown", handleClickOutside);
  }, []);

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (query.trim()) {
      setIsOpen(false);
      router.push(`/tools?q=${encodeURIComponent(query.trim())}`);
    }
  };

  const isLarge = size === "large";

  return (
    <div ref={containerRef} className={`relative w-full max-w-2xl ${className}`}>
      <form
        onSubmit={handleSubmit}
        className={`relative flex items-center w-full bg-white rounded-full shadow-lg shadow-black/10 border border-white/20 transition-all duration-300 focus-within:ring-4 focus-within:ring-indigo-500/25 focus-within:border-indigo-400 ${
          isLarge ? "p-1.5 sm:p-2" : "p-1"
        }`}
      >
        <div className="pl-4 sm:pl-5 text-slate-400">
          <Search className={isLarge ? "w-5 h-5" : "w-4 h-4"} />
        </div>

        <input
          type="text"
          value={query}
          onChange={(e) => setQuery(e.target.value)}
          onFocus={() => {
            if (query.trim().length > 1) setIsOpen(true);
          }}
          placeholder={placeholder}
          className={`w-full bg-transparent px-3 text-[#111936] placeholder:text-slate-400 focus:outline-none font-medium ${
            isLarge ? "text-sm sm:text-base py-2.5" : "text-sm py-1.5"
          }`}
          aria-label="Search tools"
        />

        {query && (
          <button
            type="button"
            onClick={() => {
              setQuery("");
              setIsOpen(false);
            }}
            className="p-1.5 text-slate-400 hover:text-slate-600 mr-1 rounded-full hover:bg-slate-100"
            aria-label="Clear search"
          >
            <X className="w-4 h-4" />
          </button>
        )}

        <button
          type="submit"
          className={`shrink-0 button-gradient text-white rounded-full flex items-center justify-center transition-all ${
            isLarge ? "w-11 h-11" : "w-9 h-9"
          }`}
          aria-label="Execute search"
        >
          <ArrowRight className={isLarge ? "w-5 h-5" : "w-4 h-4"} />
        </button>
      </form>

      {/* Live Autocomplete Dropdown */}
      {isOpen && results.length > 0 && (
        <div className="absolute top-full left-0 right-0 mt-2 bg-white rounded-2xl shadow-2xl border border-slate-100 py-2 z-50 overflow-hidden animate-in fade-in slide-in-from-top-2 duration-150">
          <div className="px-4 py-1.5 text-[11px] font-bold uppercase tracking-wider text-slate-400 border-b border-slate-100">
            Matching Tools ({results.length})
          </div>
          <div className="divide-y divide-slate-50">
            {results.map((tool) => (
              <Link
                key={tool.slug}
                href={`/tools/${tool.slug}`}
                onClick={() => setIsOpen(false)}
                className="flex items-center justify-between px-4 py-3 hover:bg-indigo-50/50 transition-colors group"
              >
                <div>
                  <div className="text-sm font-semibold text-[#111936] group-hover:text-indigo-600 transition-colors">
                    {tool.name}
                  </div>
                  <div className="text-xs text-slate-500 line-clamp-1">{tool.description}</div>
                </div>
                <ArrowRight className="w-4 h-4 text-slate-300 group-hover:text-indigo-600 group-hover:translate-x-0.5 transition-all" />
              </Link>
            ))}
          </div>
          <div className="p-2 bg-slate-50 border-t border-slate-100 text-center">
            <Link
              href={`/tools?q=${encodeURIComponent(query)}`}
              onClick={() => setIsOpen(false)}
              className="text-xs font-semibold text-indigo-600 hover:text-indigo-700"
            >
              View all results for &ldquo;{query}&rdquo; &rarr;
            </Link>
          </div>
        </div>
      )}
    </div>
  );
}

export default ToolSearch;
